456	    run.started,
457	    run.readOnly,
458	    run.state,
459	    run.pending,
460	    run.activeStep,
461	    run.moves,
462	    racing,
463	    run.canUndo,
464	    run.blockingObligations.length,
465	    due,
466	    receipts.length,
467	    settled,
468	    offeredSetups,
469	    run.autoRoll,
470	    run.canEnd.ok,
471	    closing,
472	    closingStep,
473	    pack,
474	  ]);
475	  useEffect(() => {
476	    if (!api || !publishing || !run.record || !run.state) return;
477	    const record = run.record;
478	    const state = run.state;
479	    const events = run.events;
480	    const race = raceOf(raceView.race, raceView.standings, pack.vocabulary.unit);
481	    const timer = window.setTimeout(() => {
482	      /*
483	       * The control profile rides along: the server reads it there to
484	       * decide what a tool attached to somebody's game should be told.
485	       *
486	       * With the run's setup folded into its terms, because that is what
487	       * a setup is for: one field on the wire, applied on attach, its
488	       * gifts held back on a reconnect by the record the server already
489	       * keeps. A run with a setup and no profile still has something to
490	       * send, which is why the emptiness check comes after the fold.
491	       */
492	      const profile = withChosen((record.control as ControlProfile) ?? {}, chosenFrom(record.setup));
493	      const control = isEmpty(profile) ? {} : { control: tidy(profile) };
494	      void api
495	        .putSnapshot(record.runId, {
496	          ...snapshotOf(pack, state, events, undefined, { race }),
497	          paper: paperOf(pack, state.mode),
498	          offer: currentOffer,
499	          ...control,
