504	    // eslint-disable-next-line react-hooks/exhaustive-deps
505	  }, [api, publishing, decks, run.events, pack, raceView.race, run.record?.control, run.record?.setup, currentOffer]);
506	
507	  /**
508	   * Starting a race, or joining one: an ordinary run of this pack with the
509	   * race's seed and mode, and the race told which run this is. Joining a
510	   * race that is for another pack says so rather than guessing.
511	   */
