774	            // four, would otherwise put a correction in the log saying the
775	            // tally was wrong when it was not.
776	            const by = "by" in move ? move.by : move.to - it.value;
777	            if (by === 0) return;
778	            if (it.kind === "counter") run.nudgeCounter(id, by);
779	            else run.turnResource(id, by);
780	          },
781	          clock: (id, doing) => {
782	            if (doing === "pause") run.pauseClock(id);
783	            else if (doing === "resume") run.resumeClock(id);
784	            else run.stopClock(id);
785	          },
786	          autoRoll: (on) => run.setAutoRoll(on),
787	          finish: () => {
788	            if (!closing || !closingStep || !run.canEnd.ok) return;
789	            // The page's own Finish button, to the letter: the receipts go
790	            // and the closing step ends the run in the same press.
791	            setReceipts([]);
792	            run.finish(closingStep.phase, closingStep.index);
793	          },
794	          setup: async (id) => {
795	            const picked = offeredSetups.find((s) => s.id === id);
796	            if (!picked) throw new Error("That setup is not here.");
797	            // Both halves of what Settings does in two presses: the run is
798	            // played under this from here on, and everyone attached now
799	            // gets it. The word goes out only once the write has landed,
800	            // because the server builds what a tool is sent from the run's
801	            // saved profile and would otherwise hand out the one before.
802	            await run.setSetup(chose(picked));
803	            sync.gesture(runId, "setup");
804	          },
805	          command: (id) => {
806	            const picked = offeredSetups.find((s) => s.id === id);
807	            if (!picked) throw new Error("That command is not here.");
808	            // The file's own operations, as written, rather than the run's
809	            // combined profile: the whole point is that the run is left
810	            // where it was, so nothing is read from it and nothing is
811	            // written to it. The server hands them on and forgets them.
812	            //
