814	            // write to wait for -- and because the refusal below has to
815	            // reach `takePress` rather than a promise nobody is holding.
816	            const sent = sync.gesture(runId, "command", { id: picked.id, title: picked.title, ops: picked.ops });
817	            // A deck pressed a key on a page whose socket is down. Nothing
818	            // went anywhere, and the deck is told so rather than left to
